package com.restpartijen.api.persistence

import org.jetbrains.exposed.v1.core.Table

/**
 * Table definition for suppliers (ERD §9.1, table SUPPLIERS).
 *
 * A row exists only for an account with the SUPPLIER role. A search result
 * shows the supplier's name and coordinates via SupplierSummary (§5.4).
 *
 * Owner: Eva (F1). Lives in persistence because ProductsTable refers to it and moves along (issue #36).
 */
object SuppliersTable : Table("suppliers") {
    /** Generated by the database on insert; never set by the application. */
    val id = long("id").autoIncrement()

    /**
     * The account this supplier belongs to; the database refuses an unknown user (issue #36).
     * Unique, so an account has at most one supplier.
     */
    val userId = long("user_id").references(UsersTable.id).uniqueIndex()

    /** Company name as shown in search results. */
    val name = varchar("name", length = 255)

    /** Street address of the supplier. Stored, but no endpoint returns it. */
    val address = varchar("address", length = 255)

    /** Latitude of the supplier; the app computes the distance to the collector (§18.1). */
    val latitude = double("latitude")

    /** Longitude of the supplier; see [latitude]. */
    val longitude = double("longitude")

    // Tells Exposed (and the generated SQL) which column is the primary key.
    override val primaryKey = PrimaryKey(id)
}
